'use strict';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {data:null, view:'overview', selected:null, busy:false, error:'', evidence:false, sourceDraft:'', documentId:null, invitePath:'', addingProgram:false};
const shapes = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',
  signal:'<path d="M4 16a11 11 0 0 1 16 0M7 12a7 7 0 0 1 10 0M10 8a3 3 0 0 1 4 0"/><circle cx="12" cy="20" r="1"/>',
  activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
  book:'<path d="M12 5v16m0-15C8 3 5 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-6-1-10 2Z"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c6 5 6 13 0 18-6-5-6-13 0-18Z"/>',
  file:'<path d="M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9Z"/><path d="M14 2v7h7M7 14h10M7 18h7"/>',
  people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 2 4v2"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-6 6 8 15 8 15s14-9 8-15Z"/>',
  link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 2 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0" transform="translate(1 1)"/>',
  spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',
  home:'<path d="m3 10 9-7 9 7v10H3Zm6 10v-7h6v7"/>',
  out:'<path d="M14 3h7v7m0-7-11 11M9 3H4v17h17v-5"/>',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name] || shapes.signal}</svg>`;
const labels = {DRAFT:'Ready to review',NEEDS_CLARIFICATION:'Needs your input',READY_FOR_REVIEW:'Awaiting approval',APPLYING:'Publishing',MONITORING:'Published · tracking copies',RECONFIRMATION_DUE:'Reconfirmation due',ENDED:'Arrangement ended',SUPERSEDED:'Superseded',INTERPRETING:'Interpreting',MODEL_ERROR:'Model needs attention',VERIFIED:'Verified',QUEUED:'Queued',NEEDS_OWNER:'Needs an owner',REPLACEMENT_READY:'Replacement ready',MANUALLY_CONFIRMED:'Manually confirmed',ACKNOWLEDGED:'Acknowledged',SIMULATED_PUBLISHED:'Published in simulator',RETRYABLE_FAILURE:'Retry scheduled',CANCELED:'Superseded'};
function pill(status){return `<span class="pill ${/NEEDS|DRAFT|REVIEW|ERROR|FAILURE|DUE|ENDED/.test(status)?'amber':/CANCELED|SUPERSEDED/.test(status)?'gray':/QUEUED|APPLYING|INTERPRETING/.test(status)?'blue':''}">${esc(labels[status]||status)}</span>`;}
const timeLabel = t => new Date(t*1000).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:state.data?.program.timezone||'America/Chicago',timeZoneName:'short'});
const dateLabel = dates => (dates||[]).map(d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})).join(' & ');
const current = () => state.data?.changes.find(c=>c.id===state.selected);
const publicPath = () => '/notices/'+state.data.public_id;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',5500);}
async function api(path,body){const res=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-ServiceSignal':'1'},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await res.json();}catch{throw new Error('The server returned an unexpected response. Please try again.');}if(!res.ok){let message=data.detail;if(Array.isArray(message))message=message.map(x=>x.msg.replace(/^Value error, /,'')).join(' ');const error=new Error(message||'Request failed.');error.status=res.status;throw error;}return data;}
async function refresh(render=true){state.data=await api('/api/workspace');if(render)draw();}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
const newButton=()=>`<button class="button" ${state.data?.actor?.role==='viewer'||state.data?.program.configured===false?'disabled':''} data-action="new">${icon('plus')} New update</button>`;
function illustration(){return `<svg viewBox="0 0 380 250" fill="none" aria-hidden="true"><circle cx="205" cy="128" r="100" fill="#e1e7c7"/><path d="M22 212c80-24 206-20 332 0" stroke="#c8d2ad"/><g transform="rotate(-7 166 125)"><rect x="78" y="37" width="184" height="171" rx="10" fill="#d5dabb"/><rect x="73" y="31" width="184" height="171" rx="10" fill="#fcfdf5" stroke="#c3cba9"/><rect x="96" y="53" width="67" height="6" rx="3" fill="#a3b38a"/><rect x="96" y="71" width="125" height="12" rx="3" fill="#294f3e"/><path d="M96 101h110M96 113h87" stroke="#d3dbc3" stroke-width="5" stroke-linecap="round"/><rect x="96" y="136" width="137" height="43" rx="6" fill="#edf2e1"/><rect x="109" y="148" width="18" height="18" rx="4" fill="#759158"/><path d="m113 157 4 4 6-7" stroke="white" stroke-width="2"/><path d="M138 151h79m-79 11h54" stroke="#a8bc94" stroke-width="4" stroke-linecap="round"/></g><g transform="rotate(9 280 171)"><rect x="235" y="103" width="87" height="111" rx="8" fill="#fffef8" stroke="#c4cead"/><rect x="246" y="116" width="64" height="7" rx="3" fill="#d2ddbd"/><rect x="246" y="133" width="64" height="48" rx="4" fill="#f2e7cf"/><path d="m256 158 14-13 17 16 11-8" stroke="#b69a69" stroke-width="3"/><path d="M249 194h44" stroke="#bdcaa8" stroke-width="4" stroke-linecap="round"/></g><circle cx="286" cy="61" r="24" fill="#244e3e"/><path d="m275 61 7 7 14-15" stroke="#deedb8" stroke-width="3" stroke-linecap="round"/><path d="M41 117c10-7 17-15 18-26m-8 2 9-5 4 11" stroke="#9dac7f" stroke-width="2" stroke-linecap="round"/><path d="m317 26 2 7 7 2-7 2-2 7-2-7-7-2 7-2Z" fill="#b68b5a"/><path d="m45 166 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z" fill="#b68b5a"/><circle cx="337" cy="152" r="3" fill="#acb78c"/></svg>`;}
function shell(body){const d=state.data;const active=['new','detail'].includes(state.view)?'overview':state.view;const needs=d.changes.filter(c=>['DRAFT','NEEDS_CLARIFICATION','READY_FOR_REVIEW','RECONFIRMATION_DUE'].includes(c.state)).length;return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="/" aria-label="ServiceSignal home"><span class="logo-mark">◈</span><span class="brand-text">ServiceSignal</span></a><div class="workspace-card"><span class="workspace-avatar">${icon('home')}</span><div><strong>${esc(d.program.organization)}</strong><small>${d.mode==='pilot'?'Organization workspace':'Community workspace · Demo'}</small></div></div>${d.programs.length?`<label class="label program-selector" for="program-switch">Current program</label><select id="program-switch">${d.programs.map(p=>`<option value="${esc(p.id)}" ${p.id===d.workspace_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:''}<nav aria-label="Main navigation"><p class="nav-label">YOUR WORKSPACE</p>${[['overview','grid','Overview'],['programs','calendar','Programs'],['notices','signal','Public notices'],['activity','activity','Activity'],['guide','book','Getting started'],...(d.mode==='pilot'?[['team','people','Account & team']]:[])].map(([id,ico,label])=>`<button class="nav-item ${active===id?'active':''}" data-view="${id}" ${active===id?'aria-current="page"':''} aria-label="${label}">${icon(ico)}<span>${label}</span>${id==='overview'&&needs?`<span class="nav-count">${needs}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="neighbor-note">${icon('heart')}<strong>Small updates. Real care.</strong><p>Help your neighbors arrive at the right place, at the right time.</p></div>${d.mode==='pilot'?'<button class="text-button" data-action="logout">Sign out</button>':'<button class="text-button" data-action="reset">Reset demo workspace</button>'}<div class="profile"><span class="avatar">MC</span><div><strong>${esc(d.actor?.name||'Demo coordinator')}</strong><small>${esc(d.actor?.role||'Fictional organization')}</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <strong>${({overview:'Overview',programs:'Programs',notices:'Public notices',activity:'Activity',guide:'Getting started',team:'Account & team',new:'New update',detail:'Update details'})[state.view]}</strong></div><div class="mobile-brand"><span class="logo-mark">◈</span>ServiceSignal</div><div class="top-actions"><span class="mode-badge">${d.provider==='fixture'?(d.mode==='pilot'?'Manual review · no AI call':'Guided demo · no AI call'):'Strands · '+esc(d.provider)}</span><a class="text-button" href="${publicPath()}" target="_blank" rel="noopener">Public page ${icon('out')}</a></div></header><main id="main" class="content" tabindex="-1">${!d.worker.ready?`<div class="callout" role="status">The publishing worker has not checked in recently. Approved work stays queued; publication and monitoring may be delayed.</div>`:''}${state.error?`<div class="inline-error" role="alert">${esc(state.error)}</div>`:''}${d.program.configured===false?'<div class="callout">An owner must confirm this program’s details before the first update. <button class="text-button" data-view="programs">Complete program setup</button></div>':''}${body}<footer class="footer"><span>Made for the people who keep communities connected.</span><span>${d.mode==='pilot'?'Only registered destinations are tracked':'Fictional demo · Only registered destinations are tracked'}</span></footer></main></div></div>`;}
function activityList(events){return events.slice(0,4).map(e=>`<div class="activity-item"><span class="activity-dot">${icon(e.kind==='VERIFIED'?'check':'clock')}</span><div><strong>${esc(e.kind.toLowerCase().replaceAll('_',' ').replace(/^./,c=>c.toUpperCase()))}</strong><p>${esc(e.detail)}</p><small>${timeLabel(e.created_at)}</small></div></div>`).join('');}
function programCard(){return `<div class="panel flush"><div class="program-row"><span class="program-icon">${icon('book')}</span><div class="program-info"><strong>${esc(state.data.program.name)}</strong><small>${esc(state.data.program.schedule)} · ${esc(state.data.program.timezone)}</small></div><span class="pill">Community class</span></div><div class="program-bottom"><span>4 registered surfaces</span><span>${esc(state.data.program.organization)}</span></div></div>`;}
function changeRows(){return state.data.changes.map(c=>`<button class="change-row" data-change="${esc(c.id)}"><div class="change-row-top"><strong>${esc(c.facts?.kind==='cancellation'?'Session cancellation':c.facts?.kind==='time_change'?'Session time update':state.data.program.name+' update')}</strong>${pill(c.state)}</div><p>${c.facts?esc(dateLabel(c.facts.dates)):'Review the source and confirm the affected sessions'} <span>↗</span></p></button>`).join('');}
function overview(){const d=state.data,latest=d.changes.find(c=>c.approved_at&&c.state!=='SUPERSEDED');const actions=latest?.actions||[];return heading('Your community, in the loop.','A little less coordination. A little more peace of mind.',newButton())+`<section class="hero"><div class="hero-copy"><span class="eyebrow">GOOD NEIGHBORS KEEP PEOPLE INFORMED</span><h2>A small update.<br>A better day for everyone.</h2><p>When plans change, help the right information reach the people who count on you.</p><button class="text-button" ${d.mode==='pilot'?(d.program.configured===false?'data-view="programs"':'data-action="new"'):'data-action="example"'}>${d.mode==='pilot'?(d.program.configured===false?'Finish program setup':'Prepare a program update'):'Try a two-session move'} ${icon('arrow')}</button></div><div class="hero-art">${illustration()}</div></section><div class="stats">${[['Active programs','1','Selected program','calendar'],['Verified destinations',actions.filter(a=>a.state==='VERIFIED').length,'Checked against approved facts','check'],['Needs attention',actions.filter(a=>['NEEDS_OWNER','RETRYABLE_FAILURE','ACKNOWLEDGED'].includes(a.state)).length,'Copies awaiting a person','clock'],['Public notices',d.publication?'1':'0','Accessible without an account','globe']].map(([label,value,sub,ico])=>`<div class="stat"><div class="stat-top"><span>${label}</span>${icon(ico)}</div><strong>${value}</strong><small>${sub}</small></div>`).join('')}</div><div class="dashboard-grid"><div><div class="section-head"><h2>Recent updates</h2><span class="muted small">${d.changes.length} total</span></div><div class="panel flush">${d.changes.length?changeRows():`<div class="empty-state"><div class="empty-symbol">${icon('signal')}</div><h3>Every clear update starts here.</h3><p>Paste a change to a class or program. We’ll help you prepare the right notice.</p><button class="button secondary" data-action="new">Create your first update ${icon('arrow')}</button></div>`}</div><div class="section-head"><h2>Your programs</h2><button class="text-button" data-view="programs">View program ${icon('arrow')}</button></div>${programCard()}</div><div class="right-column"><div class="section-head"><h2>Latest activity</h2><button class="text-button" data-view="activity">View all</button></div><div class="panel">${activityList(d.events)}</div><div class="tip">${icon('spark')}<div><strong>Make the next update easier.</strong><p>Put your permanent notice link on new flyers. Neighbors can check the latest details before they leave.</p></div></div></div></div>`;}
function newUpdate(){return heading('What’s changing?','Start with the message you already have.')+`<div class="form-layout"><form id="intake-form" class="panel form-panel"><span class="eyebrow">01 / SHARE THE CHANGE</span><h2>One update, a clearer plan.</h2><p class="muted small">This workspace is for ${esc(state.data.program.name)} at ${esc(state.data.program.organization)}. ${state.data.mode==='pilot'?'Use only confirmed public program details. This program uses the real clock.':'All details are fictional; the demo clock starts September 13, 2026.'}</p><label class="label" for="source">What should your community know?</label><textarea id="source" name="source" maxlength="6000" required minlength="10" placeholder="For September 15 and September 22, 2026, Digital Basics will meet in Room B at 200 Sample Street…">${esc(state.sourceDraft)}</textarea><p class="hint">Include the program, exact dates, venue, and any time changes. Paste text or extract a text-based PDF.</p><label class="label" for="pdf-source">Or start from a PDF</label><input class="input" id="pdf-source" type="file" accept="application/pdf,.pdf"><p class="hint">Up to 3 pages, 5 MB, and 6,000 extracted characters. Scanned and password-protected PDFs are unsupported. Source documents stay private to this workspace. Do not upload resident personal information.</p>${state.documentId?'<p class="hint">Original PDF preserved. Editing the extracted text creates a separate text source.</p>':''}${state.data.mode==='demo'?'<div class="examples"><button type="button" class="example-chip" data-action="fill-clean">Try a venue change</button><button type="button" class="example-chip" data-action="fill-ambiguous">Try a missing detail</button></div>':''}${state.data.provider==='fixture'?'<div class="callout">Guided mode uses fixed examples. Other messages require manual fact entry. Configure a live Strands provider to interpret arbitrary text.</div>':'<div class="callout">Strands reads the source and program context. You confirm the facts before anything can publish.</div>'}<button class="button" type="submit" ${state.busy?'disabled':''}>${icon('spark')} ${state.busy?'Preparing your draft…':'Prepare update'}</button></form><aside><div class="panel"><h2>Here’s what happens next</h2>${[['1','Understand the change','Identify affected sessions and ask about missing details.'],['2','You review and approve','Confirm the facts, destinations, and expiration notice.'],['3','Publish and check','Update the website, read it back, and track unresolved copies.']].map(([n,title,desc])=>`<div class="step"><span class="step-num">${n}</span><div><h3>${title}</h3><p>${desc}</p></div></div>`).join('')}</div><div class="tip">${icon('heart')}<div><strong>Your knowledge is the source of truth.</strong><p>The agent helps with the busywork. You decide what’s accurate and what may be published.</p></div></div></aside></div>`;}
function field(name,label,value,type='text',extra=''){return `<div class="field"><label class="label" for="${name}">${label}</label><input class="input" id="${name}" name="${name}" type="${type}" value="${esc(value)}" required ${extra}></div>`;}
function detail(){const c=current();if(!c)return overview();if(c.approved_at||c.state==='SUPERSEDED')return progress(c);const f=c.facts||c.proposal||{};const ready=c.state==='READY_FOR_REVIEW';return heading(ready?'Your update is ready for approval.':'Let’s get the details right.',esc(state.data.program.name)+' · Source-backed review · Revision '+c.revision,`<button class="button secondary" data-view="overview">Back to overview</button>`)+`<div class="form-layout"><div><div class="panel form-panel"><span class="eyebrow">02 / CONFIRM THE FACTS</span>${c.proposal?.questions?.length&&!ready?`<div class="decision"><h3>A little context is missing.</h3>${c.proposal.questions.map(q=>`<p>${esc(q)}</p>`).join('')}</div>`:''}<details ${ready?'':'open'}><summary class="details-summary">Original source message</summary><blockquote class="quote">${esc(c.source)}</blockquote>${c.metrics?.document_id?`<a class="text-button" href="/api/documents/${esc(c.metrics.document_id)}">Download original source PDF</a>`:''}</details>${c.proposal?.explanation?`<p class="muted small">${esc(c.proposal.explanation)}</p>`:''}<div class="comparison"><h3>Baseline and proposed notice</h3><table><thead><tr><th scope="col">Detail</th><th scope="col">Confirmed baseline</th><th scope="col">Proposed update</th></tr></thead><tbody>${[['Venue',state.data.program.location,f.location||'Needs confirmation'],['Room',state.data.program.room,f.room||'Needs confirmation'],['Hours',state.data.program.start_time+'–'+state.data.program.end_time,(f.start_time||'?')+'–'+(f.end_time||'?')],['Sessions',state.data.program.schedule,dateLabel(f.dates)||'Needs confirmation']].map(([label,before,after])=>`<tr><th scope="row">${esc(label)}</th><td>${esc(before)}</td><td>${esc(after)}</td></tr>`).join('')}</tbody></table><p class="hint">Public contact: ${esc(state.data.program.contact||'No contact instructions configured')}. Changed facts below must be saved before approval.</p></div><form id="review-form"><div class="grid-2"><div class="field full"><label class="label" for="kind">Type of change</label><select id="kind" name="kind">${[['relocation','Temporary venue change'],['cancellation','Session cancellation'],['time_change','Session time change']].map(([value,label])=>`<option value="${value}" ${f.kind===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field full"><label class="label" for="dates">Exact affected session dates</label><input id="dates" name="dates" class="input" required placeholder="2026-09-15, 2026-09-22" value="${esc((f.dates||[]).join(', '))}"><p class="hint">YYYY-MM-DD, separated by commas. Only these sessions will change.</p></div>${field('location','Street address',f.location||'','text','maxlength="160"')}${field('room','Room',f.room||'','text','maxlength="80"')}${field('start_time','Starts at',f.start_time||state.data.program.start_time,'time')}${field('end_time','Ends at',f.end_time||state.data.program.end_time,'time')}</div><p class="hint">Program: ${esc(state.data.program.name)} · Timezone: ${esc(state.data.program.timezone)}. Other programs stay unchanged.</p><label class="check-label"><input name="confirmed" type="checkbox" required ${ready?'checked':''}><span>I confirm these dates, venue, and hours with the program coordinator. For a cancellation, venue and hours describe the canceled sessions.</span></label><div class="form-actions"><button class="button ${ready?'secondary':''}" type="submit">${icon('check')} ${ready?'Save revised facts':'Confirm facts & prepare plan'}</button></div></form></div>${Object.keys(c.proposal?.evidence||{}).length?`<div class="panel"><h3>Evidence from the source</h3>${Object.entries(c.proposal.evidence).map(([key,value])=>`<p class="small"><strong>${esc(key.replaceAll('_',' '))}</strong> — “${esc(value)}”${c.metrics?.evidence_locations?.[key]?` <span class="muted">(${c.metrics.evidence_locations[key].page?'page '+c.metrics.evidence_locations[key].page+', ':''}line ${c.metrics.evidence_locations[key].line})</span>`:''}</p>`).join('')}<p class="hint">These quotes support the original extraction. Your confirmed edits are recorded separately.</p></div>`:''}</div><aside><div class="panel"><span class="eyebrow">YOUR PUBLICATION PLAN</span><h2>Where this update goes</h2>${[['globe','Public program page','Automatic update'],['file','Printable notice','Replacement file'],['people','Partner listing',state.data.mode==='pilot'?'Owner follow-up':'Simulated editor'],['home','Printed copies','Manual replacement']].map(([ico,name,how])=>`<div class="plan-dest">${icon(ico)}<strong>${name}</strong><span>${how}</span></div>`).join('')}${inventorySummary(c.plan_context?.inventory||state.data.inventory)}<p class="hint">Correction requests are copyable drafts. No messages are sent.</p></div><div class="panel"><h3>When the temporary change ends</h3><p class="small muted">The website will show this exact fallback until you approve a new arrangement:</p><blockquote class="quote">${esc(state.data.fallback)}</blockquote>${ready?`<a class="button secondary" href="/api/changes/${esc(c.id)}/preview.pdf?revision=${c.revision}">Preview English PDF</a>${c.plan_context?.languages?.includes('es')?`<a class="button secondary" href="/api/changes/${esc(c.id)}/preview.pdf?revision=${c.revision}&lang=es">Preview Spanish PDF</a>`:''}<p class="hint">The preview is marked unpublished and contains this revision’s exact notice facts.</p><form id="approval-form">${state.data.actor&&state.data.actor.role!=='owner'?'<p class="callout">An organization owner must approve publication.</p>':''}<label class="check-label"><input type="checkbox" required><span>I approve revision ${c.revision}, its exact facts, the website and ${c.plan_context?.languages?.includes('es')?'English and Spanish notices':'English notice'}, and the expiration fallback.</span></label>${state.data.changes.some(x=>x.id!==c.id&&x.approved_at&&x.state!=='SUPERSEDED')?'<label class="check-label"><input type="checkbox" name="replace_current" required><span>This replaces the previous public notice and its entire affected-session list. I have included every session that should remain covered.</span></label>':''}<div class="form-actions"><button class="button" ${state.data.actor&&state.data.actor.role!=='owner'?'disabled':''} type="submit">Approve these updates ${icon('arrow')}</button></div></form><p class="hint">Editing facts requires a fresh approval.</p>`:'<p class="hint">Confirm the facts to unlock publication approval.</p>'}</div></aside></div>`;}
function progress(c){const f=c.facts;return heading(c.state==='ENDED'?'The next arrangement needs you.':'One update. Every copy accounted for.',esc(f.program)+' · '+esc(dateLabel(f.dates)),`<button class="button secondary" data-view="overview">Back to overview</button>`)+`${['RECONFIRMATION_DUE','ENDED'].includes(c.state)?`<div class="reconfirm"><h2>What happens after ${esc(dateLabel([f.dates.at(-1)]))}?</h2><p>${esc(state.data.fallback)} Approve a new update to confirm the previous venue, extend the move, or choose a new arrangement.</p><button class="button secondary" data-action="new">Create follow-up update ${icon('arrow')}</button></div>`:''}<div class="form-layout"><div><div class="panel"><div class="section-head"><h2>Publication & follow-through</h2>${pill(c.state)}</div>${c.actions.map(a=>surface(a,c)).join('')}</div><div class="panel"><h3>The source behind this update</h3><blockquote class="quote">${esc(c.source)}</blockquote><p class="hint">Revision ${c.revision} approved ${timeLabel(c.approved_at)}. ${c.metrics?.live?'Interpreted by a live Strands agent.':'Guided example or manually confirmed facts; no live AI interpretation.'}</p><details><summary class="details-summary">Run and approval evidence</summary><pre class="evidence">${esc(JSON.stringify({plan_hash:c.plan_hash,metrics:c.metrics},null,2))}</pre></details></div></div><aside><div class="notice-preview"><span class="eyebrow">RESIDENT NOTICE</span><h2>${c.state==='ENDED'?'Please check before visiting':f.kind==='cancellation'?'These sessions are canceled':'A new plan for your next visit.'}</h2><p><strong>${esc(f.program)}</strong><br>${esc(state.data.program.organization)}</p><p class="preview-date">${esc(dateLabel(f.dates))}</p><p>${esc(f.start_time)}–${esc(f.end_time)} · ${esc(f.timezone)}</p><p>${esc(f.location)}<br>${esc(f.room)}</p><a class="button secondary" href="${publicPath()}" target="_blank" rel="noopener">Open public page ${icon('out')}</a><p class="hint">${c.state==='ENDED'?'Previous temporary details shown above. Future details unconfirmed.':'Preview of approved facts. The public page shows the last successfully published notice.'}</p></div><div class="panel spaced-panel"><h3>Share the useful part.</h3><p class="small muted">A permanent link neighbors can open without signing up.</p><button class="text-button" data-action="share">${icon('link')} Copy notice link</button></div>${state.data.mode==='demo'&&c.state!=='SUPERSEDED'&&c.state!=='ENDED'?`<div class="panel"><span class="eyebrow">DEMO CONTROLS</span><h3>See the end-date follow-up.</h3><p class="small muted">Advance time in this workspace only.</p><div class="form-actions"><button class="button secondary" ${state.data.mode==='pilot'?'hidden':''} data-clock="reminder">24-hour reminder</button><button class="button secondary" ${state.data.mode==='pilot'?'hidden':''} data-clock="expiry">End the arrangement</button></div>${state.data.clock_offset?`<p class="hint">Demo clock: ${timeLabel(state.data.now)}</p>`:''}</div>`:''}</aside></div>`+followUpForm(c);}
function surface(a,c){const meta={page:['globe','Public program page'],flyer:['file','Printable notice'],partner:['people','Partner directory · simulator'],print:['home','Printed copies']}[a.destination];let buttons='';if(a.destination==='page'){buttons=`<a class="text-button" href="${publicPath()}" target="_blank" rel="noopener">View page ${icon('out')}</a>`;if(['NEEDS_OWNER','RETRYABLE_FAILURE'].includes(a.state))buttons+='<button class="text-button" data-action="retry">Retry publication</button>';}
if(a.destination==='flyer'&&a.state==='REPLACEMENT_READY')buttons=`<a class="text-button" href="${publicPath()}/flyer.pdf">Download PDF ${icon('out')}</a>`;
if(a.destination==='partner'&&state.data.mode==='demo'&&!['ENDED','SUPERSEDED'].includes(c.state))buttons='<button class="text-button" data-partner="acknowledge">Simulate acknowledgment</button><button class="text-button" data-partner="publish">Simulate publication</button><button class="text-button" data-partner="fail">Simulate refusal</button><button class="text-button" data-action="copy-request">Copy correction request</button>';
if(a.destination==='partner'&&state.data.mode==='pilot')buttons='<button class="text-button" data-action="copy-request">Copy correction request</button>';
if(a.destination==='print'&&a.state==='NEEDS_OWNER'&&!['ENDED','SUPERSEDED'].includes(c.state))buttons='<button class="text-button" data-action="print-confirm">I replaced the printed copies</button>';
return `<div class="surface"><span class="surface-icon">${icon(meta[0])}</span><div class="surface-main"><div class="surface-title"><h3>${a.destination==='partner'?esc(c.plan_context?.inventory?.partner_name||meta[1]):meta[1]}</h3>${pill(a.state)}</div><p>${esc(a.detail)}</p>${a.destination==='partner'?inventorySummary(c.plan_context?.inventory||state.data.inventory):a.destination==='print'?`<p>Owner: ${esc((c.plan_context?.inventory||state.data.inventory).print_owner||'Unassigned')}</p>`:''}${a.verified_at?`<p>Checked ${timeLabel(a.verified_at)}. Verification is a timestamped observation.</p>`:''}<div class="surface-buttons">${buttons}</div>${a.observed_hash?`<details><summary class="details-summary">View read-back evidence</summary><pre class="evidence">${esc(JSON.stringify(JSON.parse(a.observed_payload||'{}'),null,2))}\nSHA-256: ${esc(a.observed_hash)}</pre></details>`:''}${a.locale_evidence?`<details><summary class="details-summary">Latest page observations</summary><pre class="evidence">${esc(JSON.stringify(JSON.parse(a.locale_evidence),null,2))}</pre></details>`:''}${a.destination==='partner'&&a.observed_payload?`<details><summary class="details-summary">Simulated published listing</summary><pre class="evidence">${esc(JSON.stringify(JSON.parse(a.observed_payload),null,2))}</pre></details>`:''}</div></div>`;}
function programs(){const p=state.data.program,locked=(state.data.mode==='demo'&&state.data.changes.length>0)||state.data.actor?.role==='editor'||state.data.actor?.role==='viewer';return heading('A place for every program.','Configure one program and the places people rely on.',newButton())+programCard()+`${state.data.programs.length>1?`<div class="panel spaced-panel"><h2>Your programs</h2><div class="examples">${state.data.programs.map(p=>`<button class="example-chip" data-select-program="${esc(p.id)}">${esc(p.name)}</button>`).join('')}</div></div>`:''}${state.data.mode==='pilot'&&state.data.actor.role==='owner'?`<form id="new-program-form" class="panel spaced-panel"><h2>Add another program</h2><p class="hint">Starts with this program’s baseline. Review its schedule and venue before creating an update.</p>${field('new_name','New program name','','text','maxlength="100"')}<button class="button secondary" type="submit">Create program</button></form>`:''}<div class="form-layout"><form id="program-form" class="panel form-panel"><h2>Confirmed baseline</h2><p class="hint">${state.data.mode==='pilot'?'Program facts must be confirmed by an organization owner.':'This is still a demonstration.'} ${state.data.mode==='pilot'?'Baseline edits apply to future reviews. Existing approved notices retain their confirmed facts.':'Setup locks after the first draft to preserve approval scope.'}</p><fieldset ${locked?'disabled':''}><legend class="label">Program details</legend><div class="grid-2">${field('name','Program name',p.name,'text','maxlength="100"')}${field('organization','Organization',p.organization,'text','maxlength="120"')}${field('timezone','IANA timezone',p.timezone)}${field('schedule','Schedule description',p.schedule,'text','maxlength="120"')}${field('location','Street address',p.location,'text','maxlength="160"')}${field('room','Room or meeting area',p.room,'text','maxlength="80"')}${field('start_time','Starts at',p.start_time,'time')}${field('end_time','Ends at',p.end_time,'time')}</div><p class="label">Recurring weekdays</p><div class="examples">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((day,i)=>`<label class="check-label"><input type="checkbox" name="weekdays" value="${i}" ${p.weekdays.includes(i)?'checked':''}>${day}</label>`).join('')}</div><label class="label" for="contact">Public contact instructions (optional)</label><input class="input" id="contact" name="contact" value="${esc(p.contact)}" maxlength="200" placeholder="A confirmed public phone number or contact instruction"><details class="spaced-panel"><summary class="details-summary">Optional Spanish notices</summary><label class="label" for="contact_es">Public contact instructions in Spanish (optional)</label><input class="input" id="contact_es" name="contact_es" value="${esc(p.contact_es||'')}" maxlength="200"><label class="check-label"><input type="checkbox" name="spanish_enabled" ${p.spanish_enabled?'checked':''}><span>Enable Spanish notices. I have reviewed the fixed Spanish wording and confirm the Spanish contact instructions. Every publication still requires approval.</span></label><details><summary class="details-summary">Review Spanish notice wording</summary><p>Este cambio se aplica solo a las sesiones indicadas a continuación. Las demás actividades no cambian.</p><p>Esta disposición temporal ha finalizado. Los detalles de las próximas sesiones aún deben confirmarse.</p><p>Cambio temporal de lugar · Cancelación de sesiones · Cambio de horario de las sesiones</p></details></details><label class="check-label"><input type="checkbox" required><span>I confirm these baseline facts and that the contact information may appear on notices.</span></label><button class="button" type="submit">Save program</button></fieldset>${locked?`<p class="callout">Program setup is locked. Temporary updates are still available. ${state.data.mode==='pilot'?'Create another program for a separate service.':'Reset this demo to configure a different program.'}</p>`:''}</form><div class="panel"><h2>Registered surfaces</h2>${[['globe','Program page','Connected'],['file','Printable flyer','Generated'],['people','Partner directory',state.data.mode==='pilot'?'Owner follow-up':'Simulation'],['home','Printed copies','Manual']].map(([ico,name,mode])=>`<div class="plan-dest">${icon(ico)}<strong>${name}</strong><span>${mode}</span></div>`).join('')}${inventoryForm()}</div></div>`;}
function notices(){return heading('Clear information. Open to everyone.','Residents need a useful notice, not another account.')+`<div class="form-layout"><div class="panel"><span class="eyebrow">PERMANENT NOTICE LINK</span><h2>${esc(state.data.program.name)}</h2><p class="muted">${state.data.publication?'Your latest published notice is available to share.':'The regular program page is ready. Publish an approved change to add a temporary notice.'}</p><div class="form-actions"><a class="button" href="${publicPath()}" target="_blank" rel="noopener">Open public notice ${icon('out')}</a><button class="button secondary" data-action="share">${icon('link')} Copy link</button>${state.data.publication?`<a class="button secondary" href="${publicPath()}/flyer.pdf">Download PDF</a>${state.data.publication?.program_context?.spanish_enabled?`<a class="button secondary" href="${publicPath()}/flyer.pdf?lang=es">Descargar PDF</a>`:''}`:''}</div><p class="hint">The same link always opens this workspace’s current publication. ${state.data.mode==='pilot'?'The link stays available after you sign out.':'Resetting the demo invalidates it.'}</p></div><div class="panel"><img src="${publicPath()}/qr.svg" width="160" height="160" alt="QR code linking to the program public notice"><h3>A flyer that points forward.</h3><p class="small muted">Use this QR code on new flyers so people can check the current details. Old printed text still needs replacing.</p><a class="text-button" href="${publicPath()}/qr.svg" download="digital-basics-qr.svg">Download QR code ${icon('arrow')}</a></div></div>`;}
function activity(){return heading('A clear record of what happened.','Approvals, publication, verification, and unresolved work.',`<a class="button secondary" href="/api/export">Export evidence ${icon('out')}</a>`)+`<div class="panel">${state.data.events.map(e=>`<div class="activity-item"><span class="activity-dot">${icon(e.kind==='VERIFIED'?'check':'clock')}</span><div><strong>${esc(e.kind.replaceAll('_',' '))}</strong><p>${esc(e.detail)}</p><small>${timeLabel(e.created_at)}</small></div></div>`).join('')}</div>`;}
function guide(){if(state.data.mode==='pilot')return heading('Keep each update accountable.','A practical workflow for your organization.')+`<div class="guide-grid">${[['1','Configure your programs','An owner confirms the baseline, contact instructions, language choices and destination owners.'],['2','Prepare and approve','Editors can prepare facts. An owner reviews the exact revision and approves publication.'],['3','Check and follow up','The worker verifies enabled notice languages. Partner and print owners still need to complete their tasks. Use follow-up drafts to confirm the next arrangement.']].map(([n,title,copy])=>`<div class="guide-card"><span class="eyebrow">${n}</span><h2>${title}</h2><p>${copy}</p></div>`).join('')}</div><div class="panel spaced-panel"><h2>Public links and private records</h2><p>Approved notices remain public after sign-out. Sources, original documents, team details and approval history require organization access. Only registered surfaces are tracked; requests are not sent automatically.</p><p>For account recovery, contact your server operator. Model availability is shown in the workspace; guided mode requires manual fact entry.</p></div>`;return heading('Good information is a community effort.','A guided tour of the prototype, with the boundaries made clear.')+`<div class="callout">This is an isolated demonstration using a fictional center and addresses. Its clock starts September 13, 2026 so the scenario stays replayable. Your changes do not affect other visitors.</div><div class="guide-grid">${[['01','Make a real update','Try the venue-change example. Confirm the dates and address, approve the plan, then open the resident page to see the actual publication.'],['02','See what still needs a person','The partner directory is a simulator. Acknowledgment does not mean publication. A printable file does not mean old flyers have been replaced.'],['03','Let temporary changes end safely','Advance the demo clock after publishing. The agent asks what happens next and publishes the approved fallback instead of guessing a venue.']].map(([n,title,copy])=>`<div class="guide-card"><span class="eyebrow">${n} / THE WORKFLOW</span><h2>${title}</h2><p>${copy}</p></div>`).join('')}</div><div class="panel spaced-panel"><h2>What’s live, and what’s a demonstration?</h2><p>Website publication, independent HTTP read-back, persistent jobs, expiry, PDFs, and QR links run locally for real.</p><p>${state.data.provider==='fixture'?'Interpretation currently uses labeled deterministic examples. A fixture run does not demonstrate the hackathon’s live Strands requirement.':'Interpretation uses the configured Strands provider. Run details record the model and token usage when available.'}</p><p>Partner editing is simulated. No email, SMS, directory integration, or real organization onboarding is connected. Demo sessions and links expire after seven days.</p><div class="form-actions"><button class="button" data-action="example">Try the guided example ${icon('arrow')}</button><button class="button secondary" data-action="reset">Reset this workspace</button></div></div>`;}
function draw(){if(!state.data)return;$('#app').innerHTML=shell(({overview,new:newUpdate,detail,programs,notices,activity,guide,team})[state.view]());}
function navigate(view){state.view=view;state.error='';draw();window.scrollTo({top:0});$('#main')?.focus({preventScroll:true});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Share it where your community already connects.');}catch{toast('Clipboard unavailable. Copy the link from the public page address bar.',true);}}
async function runAction(fn){if(state.busy)return;const form=document.querySelector('#review-form,#program-form');const saved=form?[...form.elements].filter(e=>e.name).map(e=>({name:e.name,value:e.value,checked:e.checked,type:e.type})):null;const formId=form?.id;state.busy=true;try{await fn();}catch(error){state.busy=false;state.error=error.message;toast(error.message,true);try{await refresh(false);}catch{}draw();if(saved){const restored=document.getElementById(formId);if(restored){for(const entry of saved){const input=[...restored.elements].find(e=>e.name===entry.name&&(entry.type!=='checkbox'||e.value===entry.value));if(input){input.value=entry.value;input.checked=entry.checked;}}if(formId==='review-form')restored.querySelector('input')?.dispatchEvent(new Event('input',{bubbles:true}));}}}finally{state.busy=false;}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-view],[data-action],[data-change],[data-partner],[data-clock]');if(!button)return;if(button.dataset.view){navigate(button.dataset.view);return;}if(button.dataset.change){state.selected=button.dataset.change;navigate('detail');return;}const action=button.dataset.action;
if(action==='new'){state.sourceDraft='';state.documentId=null;navigate('new');return;}
if(action==='example'){navigate('new');state.sourceDraft=state.data.example;state.documentId=null;$('#source').value=state.sourceDraft;$('#source').focus();return;}
if(action==='fill-clean'||action==='fill-ambiguous'){state.sourceDraft=state.data[action==='fill-clean'?'example':'ambiguous_example'];state.documentId=null;$('#source').value=state.sourceDraft;return;}
if(action==='share'){copy(location.origin+publicPath());return;}
if(action==='copy-request'){const f=current().facts,inventory=current().plan_context?.inventory||state.data.inventory;copy(`For ${inventory.partner_owner||'the listing owner'}${inventory.partner_url?' — '+inventory.partner_url:''}: Please update your ${f.program} listing for ${dateLabel(f.dates)}: ${f.kind}; ${f.location}, ${f.room}; ${f.start_time}–${f.end_time} ${f.timezone}. Source: ${location.origin+publicPath()}. Please confirm when published. ${state.data.mode==='demo'?'Fictional demo request.':''}`);return;}
runAction(async()=>{if(action==='logout'){await api('/api/account/logout',{});state.data=null;loginScreen();return;}if(action==='reset'){if(!window.confirm('Reset this fictional workspace? Its saved changes and public notice link will be removed.'))return;await api('/api/demo/reset',{});await api('/api/session',{});state.selected=null;state.view='overview';state.error='';await refresh();toast('Your fresh demo workspace is ready.');}
else if(action==='retry'){await api(`/api/changes/${current().id}/retry`,{});await refresh();toast('Publication retry queued.');}
else if(action==='print-confirm'){await api(`/api/changes/${current().id}/print-confirm`,{});await refresh();toast('Recorded as a manual confirmation.');}
else if(button.dataset.partner){await api(`/api/changes/${current().id}/partner/${button.dataset.partner}`,{});await refresh();toast('Partner simulation updated.');}
else if(button.dataset.clock){await api('/api/demo/clock',{change_id:current().id,stage:button.dataset.clock});await refresh();toast('Demo clock advanced. The worker will process the due job.');}});
});
document.addEventListener('input', event => {
  if (event.target.id === 'source') { state.sourceDraft=event.target.value; state.documentId=null; }
  if (event.target.closest('#review-form') && current()?.state === 'READY_FOR_REVIEW') {
    const approval = document.querySelector('#approval-form');
    if (approval) {
      approval.querySelector('[type=submit]').disabled = true;
      if (!approval.querySelector('.unsaved-warning')) {
        const warning = document.createElement('p');
        warning.className = 'hint unsaved-warning';
        warning.setAttribute('role', 'status');
        warning.textContent = 'Unsaved edits: save revised facts to generate a new approval plan.';
        approval.append(warning);
      }
    }
  }
});
document.addEventListener('submit',event=>{if(!['intake-form','review-form','approval-form','program-form','new-program-form'].includes(event.target.id))return;event.preventDefault();const form=event.target;const data=new FormData(form);runAction(async()=>{state.error='';const submit=form.querySelector('[type=submit]');submit.disabled=true;
if(form.id==='intake-form'){submit.textContent='Preparing your draft…';const result=await api('/api/changes',{source:data.get('source'),document_id:state.documentId});state.selected=result.id;state.view='detail';await refresh();window.scrollTo({top:0});toast('Draft saved. Review the facts before publishing.');}
if(form.id==='review-form'){const c=current();await api(`/api/changes/${c.id}/review`,{revision:c.revision,confirmed:data.has('confirmed'),facts:{program:state.data.program.name,kind:data.get('kind'),dates:String(data.get('dates')).split(',').map(x=>x.trim()).filter(Boolean),location:data.get('location'),room:data.get('room'),start_time:data.get('start_time'),end_time:data.get('end_time'),timezone:state.data.program.timezone}});await refresh();toast('Facts confirmed. Review the exact publication plan.');}
if(form.id==='new-program-form'){const baseline={...state.data.program,name:data.get('new_name')};delete baseline.configured;await api('/api/account/programs',baseline);state.selected=null;await refresh();toast('Program created. Confirm its baseline before the first update.');}
if(form.id==='program-form'){const baseline=Object.fromEntries(data);baseline.weekdays=data.getAll('weekdays').map(Number);baseline.spanish_enabled=data.has('spanish_enabled');await api('/api/program',baseline);await refresh();toast('Program baseline saved.');}
if(form.id==='approval-form'){const c=current();await api(`/api/changes/${c.id}/approve`,{revision:c.revision,plan_hash:c.plan_hash,replace_current:data.has('replace_current')});await refresh();window.scrollTo({top:0});toast('Approved. The worker is publishing and checking the notice.');}});});
async function boot(){try{const config=await api('/api/account/mode');if(config.mode==='pilot'&&location.hash.startsWith('#join=')){loginScreen(true);return;}await api('/api/session',{});await refresh();}catch(error){if(error.status===401){loginScreen();return;}$('#app').innerHTML=`<main class="loading"><span class="logo-mark">◈</span><h1>We couldn’t open the workspace.</h1><p>${esc(error.message)}</p><a class="button" href="/">Try again</a></main>`;}}
setInterval(async()=>{if(!state.data||state.busy||['new','programs','team'].includes(state.view)||(state.view==='detail'&&!current()?.approved_at))return;try{const old=JSON.stringify([state.data.changes,state.data.events,state.data.worker.ready]);await refresh(false);if(old!==JSON.stringify([state.data.changes,state.data.events,state.data.worker.ready]))draw();}catch{/* Preserve the last known UI during a temporary disconnect. */}},2500);
boot();


document.addEventListener('change',event=>{if(event.target.id!=='pdf-source')return;const file=event.target.files[0];if(!file)return;runAction(async()=>{if(file.size>5*1024*1024)throw new Error('PDFs must be no larger than 5 MB.');const response=await fetch('/api/documents',{method:'POST',headers:{'Content-Type':'application/pdf','X-ServiceSignal':'1'},body:file});const result=await response.json();if(!response.ok)throw new Error(result.detail||'PDF could not be read.');state.error='';state.sourceDraft=result.source;state.documentId=result.id;state.busy=false;draw();toast(`Extracted ${result.pages} page(s). Review the text before preparing the update.`);});});


function loginScreen(join=false){state.data=null;state.invitePath='';state.sourceDraft='';state.documentId=null;state.selected=null;const token=join?location.hash.slice(6):'';if(join)history.replaceState(null,'',location.pathname);state.joinToken=token;$('#app').innerHTML=`<main id="main" class="login-layout"><div class="login-intro"><a class="brand" href="/">◈ ServiceSignal</a><h1>Keep your community<br>in the loop.</h1><p>Confirm one change. Publish a clear notice. Know which copies still need attention.</p></div><form id="account-login" class="panel form-panel"><span class="eyebrow">${join?'JOIN YOUR ORGANIZATION':'YOUR ORGANIZATION WORKSPACE'}</span><h2>${join?'Accept your invitation':'Welcome back'}</h2><div id="login-error" role="alert"></div>${join?field('name','Your name','','text','autocomplete="name" maxlength="100"'):''}${field('email','Email address','','email','autocomplete="username" maxlength="254"')}${field('password',join?'Choose a password':'Password','','password',`autocomplete="${join?'new-password':'current-password'}" minlength="12" maxlength="128"`)}<button class="button" type="submit">${join?'Create account':'Sign in'}</button><p class="hint">${join?'Your invitation expires after 24 hours and can be used once.':'Access is by invitation. For account recovery, contact your organization owner or server operator.'}</p></form></main>`;}
function team(){const d=state.data;return heading('Your account and team.','Manage access to your organization’s program information.','<button class="button secondary" data-action="logout">Sign out</button>')+`<div class="form-layout"><div>${d.actor.role==='owner'?`<div class="panel"><h2>Organization members</h2>${d.team.map(m=>`<div class="program-row"><div class="program-info"><strong>${esc(m.name)}</strong><small>${esc(m.email)} · ${esc(m.role)} · ${m.active?'Active':'Inactive'}</small></div>${m.role!=='owner'&&m.active?`<button class="text-button" data-deactivate="${esc(m.id)}">Revoke access</button>`:''}</div>`).join('')}</div><form id="invite-form" class="panel form-panel"><h2>Invite a teammate</h2>${field('email','Teammate email','','email')}<label class="label" for="role">Access</label><select id="role" name="role"><option value="editor">Editor — prepare facts; owner approves publication</option><option value="viewer">Viewer — read program records</option></select><button class="button" type="submit">Create invitation link</button><p class="hint">Send the link yourself to the intended person. ServiceSignal sends no email.</p>${state.invitePath?`<label class="label" for="invite-link">Invitation link (valid for 24 hours)</label><input id="invite-link" class="input" readonly value="${esc(location.origin+state.invitePath)}">`:''}</form>`:'<div class="panel"><h2>Your access</h2><p>Your role is '+esc(d.actor.role)+'. An organization owner approves publication and manages program setup.</p></div>'}</div><form id="password-form" class="panel form-panel"><h2>Change password</h2>${field('current_password','Current password','','password','autocomplete="current-password" maxlength="128"')}${field('new_password','New password','','password','autocomplete="new-password" minlength="12" maxlength="128"')}<button class="button secondary" type="submit">Change password & sign out</button><p class="hint">Changing your password signs out all sessions.</p></form></div>`;}
document.addEventListener('submit',async event=>{if(!['account-login','invite-form','password-form'].includes(event.target.id))return;event.preventDefault();const form=event.target,body=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button.disabled=true;try{if(form.id==='account-login'){if(state.joinToken){await api('/api/account/accept',{...body,token:state.joinToken});state.joinToken='';delete body.name;}await api('/api/account/login',body);state.view='overview';await boot();}else if(form.id==='invite-form'){const result=await api('/api/account/invitations',body);state.invitePath=result.invite_path;await refresh();}else{await api('/api/account/password',body);loginScreen();toast('Password changed. Sign in again.');}}catch(error){if(form.id==='account-login')$('#login-error').textContent=error.message;else toast(error.message,true);}finally{button.disabled=false;}});
document.addEventListener('change',event=>{if(event.target.id==='program-switch')runAction(async()=>{await api(`/api/account/programs/${event.target.value}/select`,{});state.selected=null;state.view='overview';await refresh();});});
document.addEventListener('click',event=>{const button=event.target.closest('[data-deactivate]');if(button)runAction(async()=>{if(!confirm('Revoke this member’s access and sign out all their sessions?'))return;await api(`/api/account/members/${button.dataset.deactivate}/deactivate`,{});await refresh();toast('Member access revoked.');});});

document.addEventListener('click',event=>{const button=event.target.closest('[data-select-program]');if(button)runAction(async()=>{await api(`/api/account/programs/${button.dataset.selectProgram}/select`,{});state.selected=null;await refresh();});});


function inventorySummary(v){return `<p class="hint">Listing owner: ${esc(v.partner_owner||'Unassigned')}${v.partner_url?` · <a href="${esc(v.partner_url)}" target="_blank" rel="noopener noreferrer">Open registered listing</a>`:''}<br>Print owner: ${esc(v.print_owner||'Unassigned')}</p>`;}
function inventoryForm(){const v=state.data.inventory,locked=state.data.actor&&state.data.actor.role!=='owner';return `<form id="inventory-form"><h3>Who updates the other copies?</h3><fieldset ${locked?'disabled':''}>${field('partner_name','Listing name',v.partner_name,'text','maxlength="100"')}<label class="label" for="partner_owner">Listing owner (optional)</label><input class="input" id="partner_owner" name="partner_owner" value="${esc(v.partner_owner)}" maxlength="120"><label class="label" for="partner_url">Public listing URL (optional)</label><input class="input" type="url" id="partner_url" name="partner_url" value="${esc(v.partner_url)}" placeholder="https://" maxlength="500"><label class="label" for="print_owner">Print replacement owner (optional)</label><input class="input" id="print_owner" name="print_owner" value="${esc(v.print_owner)}" maxlength="120"><label class="label" for="print_notes">Where printed copies are posted (optional)</label><textarea id="print_notes" name="print_notes" maxlength="500">${esc(v.print_notes)}</textarea><button class="button secondary" type="submit">Save destination owners</button></fieldset><p class="hint">The external listing is read-only. Saving a URL grants no publishing access. These owners are included in future approval plans.</p></form>`;}
function followUpForm(c){if(c.state==='SUPERSEDED'||state.data.actor?.role==='viewer')return '';return `<form id="follow-up-form" class="panel form-panel spaced-panel"><h2>What happens after these sessions?</h2><p class="hint">Prepare a new draft. Nothing changes until an owner confirms and approves it.</p><label class="label" for="arrangement">Next arrangement</label><select name="arrangement" id="arrangement"><option value="extend">Continue this arrangement on new dates</option><option value="restore">Propose the currently configured baseline</option><option value="new">Enter a different arrangement</option></select>${field('next_dates','Exact next session dates','','text','placeholder="YYYY-MM-DD, YYYY-MM-DD"')}<button class="button secondary" type="submit">Prepare follow-up draft</button></form>`;}
document.addEventListener('submit',event=>{if(!['inventory-form','follow-up-form'].includes(event.target.id))return;event.preventDefault();const form=event.target,data=new FormData(form);runAction(async()=>{if(form.id==='inventory-form'){await api('/api/inventory',Object.fromEntries(data));await refresh();toast('Destination owners saved for future plans.');}else{const next=await api(`/api/changes/${current().id}/follow-up`,{arrangement:data.get('arrangement'),dates:String(data.get('next_dates')).split(',').map(x=>x.trim()).filter(Boolean)});state.selected=next.id;state.view='detail';await refresh();window.scrollTo({top:0});toast('Follow-up draft prepared. Confirm the arrangement before approval.');}});});
